enum ScoreError:
    malformed
    invalid_score
    duplicate_name

enum ScoreResult:
    accepted(scores: map[string, int64])
    rejected(line: int64, error: ScoreError)

function parse_scores(lines: list[string]) returns ScoreResult:
    mutable map[string, int64] scores = map.new[string, int64]()
    mutable int64 line_number = 0

    for line in lines:
        list[string] fields = string.split(line, "=")
        int64 field_count = list.length[string](view fields)

        if field_count != 2:
            return ScoreResult.rejected(line: line_number, error: ScoreError.malformed)

        mutable string name = ""
        mutable string score_text = ""
        mutable int64 field_index = 0

        for field in fields:
            if field_index == 0:
                name = field
            else:
                score_text = field
            field_index = field_index + 1

        if name == "":
            return ScoreResult.rejected(line: line_number, error: ScoreError.malformed)

        int64 score = int64.from_string(score_text) handle error:
            return ScoreResult.rejected(line: line_number, error: ScoreError.invalid_score)

        if string.from_int64(score) != score_text:
            return ScoreResult.rejected(line: line_number, error: ScoreError.invalid_score)

        if map.contains[string, int64](view scores, name):
            return ScoreResult.rejected(line: line_number, error: ScoreError.duplicate_name)

        scores = map.set[string, int64](scores, name, score)
        line_number = line_number + 1

    return ScoreResult.accepted(scores: scores)

