    end: int64

function merge_sorted_intervals(intervals: list[Interval]) returns list[Interval]:
    mutable list[Interval] merged = list.new[Interval]()
    mutable Interval current = Interval(start: 0, end: 0)
    mutable bool has_current = false

    for interval in intervals:
        if not has_current:
            current = Interval(start: interval.start, end: interval.end)
            has_current = true
        else if interval.start <= current.end:
            if interval.end > current.end:
                current = Interval(start: current.start, end: interval.end)
        else:
            merged = list.append[Interval](merged, current)
            current = Interval(start: interval.start, end: interval.end)

    if has_current:
        merged = list.append[Interval](merged, current)

    return merged

