namespace benchmark

enum OrderState:
    draft
    submitted
    paid
    shipped
    cancelled

enum OrderEvent:
    submit
    pay
    ship
    cancel

enum TransitionError:
    event_not_allowed
    terminal_state

enum TransitionResult:
    accepted(state: OrderState)
    rejected(error: TransitionError)

function transition(state: OrderState, event: OrderEvent) returns TransitionResult:
    match state:
        draft:
            match event:
                submit:
                    return TransitionResult.accepted(state: OrderState.submitted)
                pay:
                    return TransitionResult.rejected(error: TransitionError.event_not_allowed)
                ship:
                    return TransitionResult.rejected(error: TransitionError.event_not_allowed)
                cancel:
                    return TransitionResult.accepted(state: OrderState.cancelled)
        submitted:
            match event:
                submit:
                    return TransitionResult.rejected(error: TransitionError.event_not_allowed)
                pay:
                    return TransitionResult.accepted(state: OrderState.paid)
                ship:
                    return TransitionResult.rejected(error: TransitionError.event_not_allowed)
                cancel:
                    return TransitionResult.accepted(state: OrderState.cancelled)
        paid:
            match event:
                submit:
                    return TransitionResult.rejected(error: TransitionError.event_not_allowed)
                pay:
                    return TransitionResult.rejected(error: TransitionError.event_not_allowed)
                ship:
                    return TransitionResult.accepted(state: OrderState.shipped)
                cancel:
                    return TransitionResult.accepted(state: OrderState.cancelled)
        shipped:
            match event:
                submit:
                    return TransitionResult.rejected(error: TransitionError.terminal_state)
                pay:
                    return TransitionResult.rejected(error: TransitionError.terminal_state)
                ship:
                    return TransitionResult.rejected(error: TransitionError.terminal_state)
                cancel:
                    return TransitionResult.rejected(error: TransitionError.terminal_state)
        cancelled:
            match event:
                submit:
                    return TransitionResult.rejected(error: TransitionError.terminal_state)
                pay:
                    return TransitionResult.rejected(error: TransitionError.terminal_state)
                ship:
                    return TransitionResult.rejected(error: TransitionError.terminal_state)
                cancel:
                    return TransitionResult.rejected(error: TransitionError.terminal_state)

namespace benchmark

function non_negative(value: int64) returns int64:
    if value < 0:
        return -value
    return value

function signed_gcd(a: int64, b: int64) returns int64:
    mutable int64 left = non_negative(a)
    mutable int64 right = non_negative(b)
    while right != 0:
        mutable int64 remainder = left modulo right
        left = right
        right = remainder
    return left
